// fa("faCheck", "h-3 w-3") and lu("play", "size-3.5") return inline SVG strings.
function fa(name, cls = "", style = "") {
  const [w, h, d] = FA[name];
  return `<svg class="fa ${cls}" style="${style}" viewBox="0 0 ${w} ${h}" fill="currentColor" aria-hidden="true"><path d="${d}"/></svg>`;
}
function lu(name, cls = "", style = "") {
  return `<svg class="lu ${cls}" style="${style}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${LU[name]}</svg>`;
}
